INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Google', 'Software Engineer', 'DSA', 'MEDIUM', 'Given an array of integers, find two numbers that add up to a target sum and return their indices.', 'Use a hashmap to store complement values; iterate once, checking if the current element exists in the map. O(n) time and space.', ARRAY['arrays','hashmap','two-sum']),
('Google', 'Software Engineer', 'DSA', 'HARD', 'Given a list of meeting time intervals, find the minimum number of conference rooms required.', 'Sort start and end times separately; use a two-pointer or min-heap approach to track overlapping intervals. O(n log n).', ARRAY['intervals','heap','greedy']),
('Google', 'Software Engineer', 'DSA', 'MEDIUM', 'Serialize and deserialize a binary tree.', 'Use BFS or pre-order DFS with null markers; ensure the deserialization reconstructs the exact tree structure.', ARRAY['binary-tree','bfs','serialization']),
('Google', 'Software Engineer', 'DSA', 'HARD', 'Find the median of two sorted arrays in O(log(m+n)) time.', 'Binary search on the smaller array to find the correct partition; ensure left halves combined are less than or equal to right halves.', ARRAY['binary-search','arrays','divide-and-conquer']),
('Google', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a 2D grid of 0s and 1s, count the number of islands using DFS or BFS.', 'Traverse grid; on finding a 1, increment count and flood-fill connected 1s to 0. O(m*n) time.', ARRAY['graphs','dfs','matrix']),
('Google', 'Software Engineer', 'DSA', 'EASY', 'Check if a string is a valid palindrome, ignoring non-alphanumeric characters and case.', 'Use two pointers from both ends; skip non-alphanumeric characters and compare lowercased characters.', ARRAY['strings','two-pointer','palindrome']),
('Google', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a string, find the length of the longest substring without repeating characters.', 'Sliding window with a hashmap or set tracking character positions; expand right, shrink left on duplicate. O(n).', ARRAY['strings','sliding-window','hashmap']),
('Google', 'Software Engineer', 'DSA', 'HARD', 'Word Break II: given a string and a dictionary, return all possible sentences formed by breaking the string into valid words.', 'Use DFS with memoization; cache results for each starting index to avoid recomputation.', ARRAY['dynamic-programming','backtracking','memoization']),
('Google', 'Software Engineer', 'DSA', 'MEDIUM', 'Design a data structure that supports insert, delete, and getRandom in O(1) average time.', 'Combine a hashmap (value to index) with a dynamic array; swap deleted element with last before removing.', ARRAY['design','hashmap','arrays']),
('Google', 'Software Engineer', 'DSA', 'EASY', 'Merge two sorted linked lists into one sorted list.', 'Use a dummy head node and iteratively compare the two list heads, appending the smaller node.', ARRAY['linked-list','merge','sorting']),
('Google', 'Software Engineer', 'System Design', 'HARD', 'Design Google Search''s autocomplete feature.', 'Use a Trie with ranked suggestions; cache top-k results at each node; discuss sharding by prefix, low-latency read replicas, and CDN for edge caching.', ARRAY['trie','caching','distributed-systems']),
('Google', 'Software Engineer', 'System Design', 'HARD', 'Design a URL shortening service like bit.ly.', 'Hash or encode a long URL to a short key; store in a key-value store; handle redirects with 301/302; discuss collision handling, analytics, and expiry.', ARRAY['hashing','key-value-store','scalability']),
('Google', 'Software Engineer', 'System Design', 'MEDIUM', 'Design a rate limiter for a public API.', 'Token bucket or sliding window counter; store counters in Redis; discuss per-user vs global limits and distributed synchronization.', ARRAY['rate-limiting','redis','distributed-systems']),
('Google', 'Software Engineer', 'Behavioral', 'EASY', 'Tell me about a time you disagreed with your team and how you resolved it.', 'Look for structured conflict resolution: listening to all perspectives, using data to support position, reaching consensus, and moving forward constructively.', ARRAY['conflict-resolution','teamwork','communication']),
('Google', 'Software Engineer', 'Behavioral', 'MEDIUM', 'Describe a project where you had ambiguous requirements. How did you handle it?', 'Candidate should demonstrate proactive clarification, breaking ambiguity into hypotheses, iterating quickly, and aligning with stakeholders.', ARRAY['ambiguity','problem-solving','stakeholder-management']),
('Google', 'Software Engineer', 'Technical', 'MEDIUM', 'Explain the difference between a process and a thread. When would you use one over the other?', 'Processes have separate memory spaces; threads share memory within a process. Use threads for shared-memory concurrency; processes for isolation and fault tolerance.', ARRAY['operating-systems','concurrency','processes']),
('Google', 'Software Engineer', 'Technical', 'MEDIUM', 'What happens when you type a URL into a browser and press Enter?', 'DNS resolution, TCP handshake, TLS negotiation, HTTP request, server processing, HTTP response, browser rendering. Cover each step briefly.', ARRAY['networking','dns','http']),
('Google', 'Software Engineer', 'Technical', 'HARD', 'Explain how garbage collection works in Java or Go, including different GC algorithms.', 'Cover mark-and-sweep, generational GC (young/old gen), stop-the-world pauses, and concurrent/parallel collectors like G1 or Go''s tricolor mark.', ARRAY['memory-management','garbage-collection','jvm']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Microsoft', 'Software Engineer', 'DSA', 'EASY', 'Reverse a linked list iteratively and recursively.', 'Iteratively track prev/curr/next pointers; recursively reverse the rest then fix the current node''s next pointer.', ARRAY['linked-list','recursion']),
('Microsoft', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a binary tree, perform a level-order traversal and return nodes grouped by level.', 'Use a queue; process each level by iterating over the current queue size, appending children for the next level.', ARRAY['binary-tree','bfs','queue']),
('Microsoft', 'Software Engineer', 'DSA', 'MEDIUM', 'Implement LRU Cache with get and put operations in O(1) time.', 'Use a doubly-linked list for order and a hashmap from key to list node; move accessed nodes to head, evict from tail.', ARRAY['design','hashmap','linked-list']),
('Microsoft', 'Software Engineer', 'DSA', 'HARD', 'Given a list of words and a width, format the text so each line has exactly the specified width with justified spacing.', 'Greedily pack words per line; distribute extra spaces evenly from left; last line is left-aligned.', ARRAY['strings','greedy','simulation']),
('Microsoft', 'Software Engineer', 'DSA', 'MEDIUM', 'Find all permutations of a given string or array.', 'Use backtracking; swap elements at each position and recurse; restore state after recursion.', ARRAY['backtracking','recursion','permutations']),
('Microsoft', 'Software Engineer', 'DSA', 'EASY', 'Determine if a binary tree is a valid Binary Search Tree.', 'Pass min/max bounds recursively; left subtree values must be below current, right above. O(n).', ARRAY['binary-tree','bst','recursion']),
('Microsoft', 'Software Engineer', 'DSA', 'HARD', 'Find the largest rectangle in a histogram.', 'Use a monotonic stack to track indices; on each bar, pop shorter bars and compute area using the current bar as height.', ARRAY['stack','arrays','monotonic-stack']),
('Microsoft', 'Software Engineer', 'DSA', 'MEDIUM', 'Clone a graph where each node has a value and a list of neighbors.', 'DFS or BFS with a hashmap from original node to cloned node; clone neighbors recursively.', ARRAY['graphs','dfs','hashmap']),
('Microsoft', 'Software Engineer', 'DSA', 'EASY', 'Find the first non-repeating character in a string.', 'Use a frequency hashmap; iterate again to find the first character with count 1.', ARRAY['strings','hashmap','frequency']),
('Microsoft', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a rotated sorted array, search for a target element efficiently.', 'Modified binary search; determine which half is sorted, check if target falls in it, then adjust bounds.', ARRAY['binary-search','arrays','rotated-array']),
('Microsoft', 'Software Engineer', 'System Design', 'HARD', 'Design Microsoft Teams or a similar real-time messaging platform.', 'Discuss WebSocket connections for real-time delivery, message persistence in a distributed DB, presence service, notification fanout, and file storage via blob store.', ARRAY['real-time','websockets','distributed-systems']),
('Microsoft', 'Software Engineer', 'System Design', 'MEDIUM', 'Design a notification service that delivers push/email/SMS notifications at scale.', 'Event-driven architecture with a queue (Kafka); per-channel workers; retry with exponential backoff; deduplication; user preference store.', ARRAY['queues','event-driven','scalability']),
('Microsoft', 'Software Engineer', 'Behavioral', 'EASY', 'Describe a situation where you had to learn a new technology quickly to deliver a project.', 'Look for self-directed learning, resourcefulness, concrete outcome, and how learning was applied under time pressure.', ARRAY['learning','adaptability','delivery']),
('Microsoft', 'Software Engineer', 'Behavioral', 'MEDIUM', 'Tell me about a time you received critical feedback. How did you respond?', 'Candidate should show openness, specific action taken to improve, and measurable result after the change.', ARRAY['feedback','growth-mindset','self-awareness']),
('Microsoft', 'Software Engineer', 'Technical', 'MEDIUM', 'What is the difference between TCP and UDP? When would you use each?', 'TCP is connection-oriented, reliable, ordered; UDP is connectionless, lower latency. Use TCP for HTTP/file transfers; UDP for video streaming, gaming, DNS.', ARRAY['networking','tcp-udp','protocols']),
('Microsoft', 'Software Engineer', 'Technical', 'MEDIUM', 'Explain SOLID principles with an example for each.', 'Cover Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion with a brief code or design scenario for each.', ARRAY['oop','design-principles','solid']),
('Microsoft', 'Software Engineer', 'Technical', 'HARD', 'How does the .NET CLR manage memory, and what is the role of the Large Object Heap?', 'CLR uses generational GC (Gen 0/1/2); LOH stores objects >85 KB, is collected less frequently, and can cause fragmentation.', ARRAY['memory-management','dotnet','garbage-collection']),
('Microsoft', 'Software Engineer', 'Technical', 'EASY', 'What is a deadlock? How can it be prevented?', 'Deadlock occurs when two or more threads wait on each other indefinitely. Prevent via lock ordering, timeouts, or deadlock detection algorithms.', ARRAY['operating-systems','concurrency','deadlock']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Amazon', 'SDE-1', 'DSA', 'MEDIUM', 'Given a string, find the longest palindromic substring.', 'Expand-around-center for each character and each pair; track max length. O(n^2) time, O(1) space. Mention Manacher''s algorithm for O(n).', ARRAY['strings','dynamic-programming','palindrome']),
('Amazon', 'SDE-1', 'DSA', 'HARD', 'Given n non-negative integers representing heights of bars, compute how much rainwater can be trapped.', 'Precompute left_max and right_max arrays, then water at each index is min(left_max, right_max) - height[i]. Two-pointer approach also acceptable.', ARRAY['arrays','two-pointer','dynamic-programming']),
('Amazon', 'SDE-1', 'DSA', 'MEDIUM', 'Find the kth largest element in an unsorted array without fully sorting it.', 'Use a min-heap of size k, or QuickSelect for average O(n). Know the trade-offs between approaches.', ARRAY['heap','quickselect','sorting']),
('Amazon', 'SDE-1', 'DSA', 'EASY', 'Determine if two strings are anagrams of each other.', 'Sort both strings and compare, or use a character frequency map and check equality. O(n) with hashmap.', ARRAY['strings','hashmap','frequency']),
('Amazon', 'SDE-1', 'DSA', 'MEDIUM', 'Given a binary tree, find the maximum path sum where a path can start and end at any node.', 'DFS returning max gain from each node; at each node, consider including both children; track global max.', ARRAY['binary-tree','dfs','dynamic-programming']),
('Amazon', 'SDE-1', 'DSA', 'HARD', 'Given a set of words, find the shortest transformation sequence from a start word to an end word changing one letter at a time, using only dictionary words.', 'BFS treating each word as a graph node; generate all one-letter-different neighbors; shortest path = BFS depth.', ARRAY['graphs','bfs','strings']),
('Amazon', 'SDE-1', 'DSA', 'MEDIUM', 'Design an algorithm to flatten a nested list iterator.', 'Use a stack initialized with the list in reverse; on next(), push nested list items back; hasNext() ensures top is integer.', ARRAY['design','stack','iterator']),
('Amazon', 'SDE-1', 'DSA', 'EASY', 'Given a sorted array, remove duplicates in-place and return the new length.', 'Use a slow pointer tracking the last unique position; advance fast pointer and copy on new value.', ARRAY['arrays','two-pointer','in-place']),
('Amazon', 'SDE-1', 'System Design', 'HARD', 'Design Amazon''s product recommendation system.', 'Discuss collaborative filtering vs content-based; offline batch jobs (Spark/EMR) generating recommendations stored in a low-latency read store (DynamoDB/ElastiCache); A/B testing layer.', ARRAY['machine-learning','distributed-systems','caching']),
('Amazon', 'SDE-1', 'System Design', 'HARD', 'Design an order management system for Amazon''s e-commerce platform.', 'Cover order placement API, inventory reservation, payment service integration, eventual consistency, event-driven state machine for order lifecycle, and dead-letter queues for failures.', ARRAY['distributed-systems','event-driven','scalability']),
('Amazon', 'SDE-1', 'System Design', 'MEDIUM', 'Design a distributed key-value store like DynamoDB.', 'Cover consistent hashing for partitioning, replication factor, quorum reads/writes, vector clocks for conflict resolution, and gossip protocol for membership.', ARRAY['distributed-systems','consistent-hashing','replication']),
('Amazon', 'SDE-1', 'Behavioral', 'MEDIUM', 'Tell me about a time you delivered a project under a tight deadline. How did you prioritize?', 'Should demonstrate Customer Obsession and Deliver Results LPs: scoping, ruthless prioritization, clear communication of trade-offs, and on-time delivery.', ARRAY['leadership-principles','delivery','prioritization']),
('Amazon', 'SDE-1', 'Behavioral', 'MEDIUM', 'Describe a time you took ownership of a problem that was outside your direct responsibilities.', 'Maps to Ownership LP: proactive identification of risk, stepping up without being asked, and driving resolution to completion.', ARRAY['leadership-principles','ownership','initiative']),
('Amazon', 'SDE-1', 'Behavioral', 'MEDIUM', 'Give an example of when you used data to influence a decision.', 'Maps to Are Right A Lot / Invent and Simplify: quantitative reasoning, hypothesis testing, and persuading stakeholders with metrics.', ARRAY['leadership-principles','data-driven','communication']),
('Amazon', 'SDE-1', 'Behavioral', 'EASY', 'Tell me about a time you disagreed with a manager. What did you do?', 'Maps to Have Backbone; Disagree and Commit LP: respectfully voicing concerns with evidence, then fully committing once a decision is made.', ARRAY['leadership-principles','conflict-resolution','integrity']),
('Amazon', 'SDE-1', 'Technical', 'MEDIUM', 'Explain the CAP theorem and how Amazon''s DynamoDB addresses it.', 'CAP: can only guarantee two of Consistency, Availability, Partition Tolerance. DynamoDB favors Availability and Partition Tolerance with eventual consistency by default, tunable to strong.', ARRAY['distributed-systems','cap-theorem','databases']),
('Amazon', 'SDE-1', 'Technical', 'EASY', 'What is the difference between SQL and NoSQL databases? When would you choose each?', 'SQL: structured, ACID, relational; NoSQL: flexible schema, horizontally scalable, BASE. Choose SQL for complex queries/transactions; NoSQL for high-throughput, variable schema.', ARRAY['databases','sql','nosql']),
('Amazon', 'SDE-1', 'Technical', 'HARD', 'Explain how microservices communicate and handle failures in a distributed system.', 'Synchronous via REST/gRPC; asynchronous via message queues (SQS/Kafka). Handle failures with circuit breakers, retries with backoff, bulkheads, and idempotency.', ARRAY['microservices','distributed-systems','resilience']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('TCS', 'Assistant System Engineer', 'DSA', 'EASY', 'Write a program to check if a number is prime.', 'Check divisibility from 2 to sqrt(n); return false if any divisor found, else true. O(sqrt(n)).', ARRAY['math','loops','prime']),
('TCS', 'Assistant System Engineer', 'DSA', 'EASY', 'Reverse a string without using built-in reverse functions.', 'Use two pointers from both ends, swap characters until they meet. O(n) time, O(1) extra space.', ARRAY['strings','two-pointer','in-place']),
('TCS', 'Assistant System Engineer', 'DSA', 'MEDIUM', 'Find the second largest element in an array in a single traversal.', 'Track largest and second-largest in one pass; update both carefully when a new max is found.', ARRAY['arrays','traversal','searching']),
('TCS', 'Assistant System Engineer', 'DSA', 'EASY', 'Print Pascal''s triangle up to n rows.', 'Each element is the sum of the two elements above it; use the previous row to compute the next. O(n^2).', ARRAY['arrays','math','pattern']),
('TCS', 'Assistant System Engineer', 'DSA', 'MEDIUM', 'Implement a stack using two queues.', 'Push: enqueue to q1, then rotate all elements from q2 to q1 and swap; pop from front of q1. Alternatively, make push costly or pop costly.', ARRAY['stack','queue','design']),
('TCS', 'Assistant System Engineer', 'Technical', 'EASY', 'What are the four pillars of Object-Oriented Programming?', 'Encapsulation, Abstraction, Inheritance, and Polymorphism — briefly explain each with a real-world analogy.', ARRAY['oop','fundamentals','concepts']),
('TCS', 'Assistant System Engineer', 'Technical', 'MEDIUM', 'What is normalization in databases? Explain up to 3NF.', '1NF: atomic values, no repeating groups. 2NF: no partial dependency on composite key. 3NF: no transitive dependency on non-key attribute.', ARRAY['dbms','normalization','sql']),
('TCS', 'Assistant System Engineer', 'Technical', 'EASY', 'What is the difference between a compiler and an interpreter?', 'Compiler translates the entire source code before execution; interpreter translates and executes line by line. Compilers generally produce faster execution; interpreters are easier to debug interactively.', ARRAY['compilers','programming-concepts','fundamentals']),
('TCS', 'Assistant System Engineer', 'Technical', 'MEDIUM', 'Explain virtual memory and paging.', 'Virtual memory allows processes to use more memory than physically available by mapping virtual pages to physical frames via a page table; page faults trigger disk I/O.', ARRAY['operating-systems','memory-management','paging']),
('TCS', 'Assistant System Engineer', 'Aptitude', 'EASY', 'A train travels 60 km/h for the first half of the distance and 40 km/h for the second half. What is the average speed for the whole journey?', 'Harmonic mean of speeds: 2*60*40/(60+40) = 48 km/h. Key insight: average speed for equal distances uses harmonic mean, not arithmetic mean.', ARRAY['aptitude','speed-distance','arithmetic']),
('TCS', 'Assistant System Engineer', 'Aptitude', 'MEDIUM', 'How many ways can 6 people be seated in a row such that two specific people are always adjacent?', 'Treat the pair as one unit: 5! arrangements of units * 2! arrangements within the pair = 240.', ARRAY['aptitude','permutations','combinatorics']),
('TCS', 'Assistant System Engineer', 'Aptitude', 'EASY', 'Find the missing number in the series: 2, 6, 12, 20, 30, __', 'Pattern: n*(n+1); next is 6*7 = 42.', ARRAY['aptitude','series','number-patterns']),
('TCS', 'Assistant System Engineer', 'Aptitude', 'MEDIUM', 'A and B together complete a task in 12 days. A alone takes 20 days. How many days does B alone take?', '1/B = 1/12 - 1/20 = (5-3)/60 = 2/60; B = 30 days.', ARRAY['aptitude','work-rate','arithmetic']),
('TCS', 'Assistant System Engineer', 'Aptitude', 'EASY', 'If the cost price is Rs 500 and selling price is Rs 600, find the profit percentage.', 'Profit = 100; Profit% = (100/500)*100 = 20%.', ARRAY['aptitude','profit-loss','arithmetic']),
('TCS', 'Assistant System Engineer', 'Aptitude', 'MEDIUM', 'Decode the series of letters: Z, X, V, T, __, P', 'Each letter skips one (every alternate letter in reverse); missing is R.', ARRAY['aptitude','letter-series','logical-reasoning']),
('TCS', 'Assistant System Engineer', 'Behavioral', 'EASY', 'Why do you want to join TCS?', 'Look for awareness of TCS''s scale, learning culture, and digital transformation initiatives; genuine interest beyond just job security.', ARRAY['behavioral','company-fit','motivation']),
('TCS', 'Assistant System Engineer', 'Technical', 'MEDIUM', 'Explain the difference between GET and POST HTTP methods.', 'GET retrieves data and parameters are in the URL (idempotent, cacheable); POST sends data in the request body for creating/modifying resources (not idempotent).', ARRAY['networking','http','web']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Infosys', 'Systems Engineer', 'DSA', 'EASY', 'Find all pairs in an array that sum to a given value k.', 'Sort and use two pointers, or use a hashset to check for complement of each element in O(n).', ARRAY['arrays','hashmap','two-pointer']),
('Infosys', 'Systems Engineer', 'DSA', 'MEDIUM', 'Write a program to detect a cycle in a linked list.', 'Floyd''s cycle detection: slow and fast pointers; if they ever meet, a cycle exists. O(n) time, O(1) space.', ARRAY['linked-list','two-pointer','cycle-detection']),
('Infosys', 'Systems Engineer', 'DSA', 'EASY', 'Find the factorial of a number using recursion and iteration.', 'Recursive: base case n==1; Iterative: multiply i from 1 to n. Note stack overflow risk for large n in recursion.', ARRAY['recursion','math','loops']),
('Infosys', 'Systems Engineer', 'DSA', 'MEDIUM', 'Given a matrix, rotate it 90 degrees clockwise in-place.', 'Transpose the matrix (swap matrix[i][j] with matrix[j][i]), then reverse each row.', ARRAY['arrays','matrix','in-place']),
('Infosys', 'Systems Engineer', 'DSA', 'MEDIUM', 'Implement binary search on a sorted array and analyze its complexity.', 'Compare mid element to target; adjust left/right bounds. O(log n) time. Be precise about handling even/odd lengths and off-by-one errors.', ARRAY['binary-search','arrays','searching']),
('Infosys', 'Systems Engineer', 'DSA', 'HARD', 'Find the longest increasing subsequence in an array.', 'DP in O(n^2): dp[i] = max(dp[j]+1) for all j<i where arr[j]<arr[i]. O(n log n) with patience sorting/binary search approach is a bonus.', ARRAY['dynamic-programming','arrays','subsequence']),
('Infosys', 'Systems Engineer', 'Technical', 'EASY', 'What is the difference between primary key and unique key?', 'Primary key: uniquely identifies a row, cannot be NULL, only one per table. Unique key: also enforces uniqueness but can contain NULL, multiple allowed per table.', ARRAY['dbms','sql','constraints']),
('Infosys', 'Systems Engineer', 'Technical', 'MEDIUM', 'Explain the concept of indexing in databases and its trade-offs.', 'Index speeds up SELECT queries by allowing faster lookup (B-tree or hash index); trade-off is slower INSERT/UPDATE/DELETE and additional storage.', ARRAY['dbms','indexing','performance']),
('Infosys', 'Systems Engineer', 'Technical', 'EASY', 'What are the differences between abstract classes and interfaces?', 'Abstract class: can have state and method implementations, single inheritance. Interface: no state (in Java 7-), multiple implementation. Java 8+ interfaces can have default methods.', ARRAY['oop','java','design']),
('Infosys', 'Systems Engineer', 'Technical', 'MEDIUM', 'Explain the OSI model and the role of each layer.', 'Seven layers: Physical, Data Link, Network, Transport, Session, Presentation, Application. Each encapsulates the layer below; give one protocol example per layer.', ARRAY['networking','osi-model','protocols']),
('Infosys', 'Systems Engineer', 'Aptitude', 'EASY', 'A boat goes 15 km upstream in 5 hours and 15 km downstream in 3 hours. Find the speed of the stream.', 'Speed upstream = 3 km/h, downstream = 5 km/h; stream speed = (5-3)/2 = 1 km/h.', ARRAY['aptitude','boats-streams','arithmetic']),
('Infosys', 'Systems Engineer', 'Aptitude', 'MEDIUM', 'In a class of 60 students, 40% are girls. How many additional girls must be added to make girls 50% of the class?', '24 girls currently; let x be added: (24+x)/(60+x) = 0.5; solving gives x = 12.', ARRAY['aptitude','percentages','algebra']),
('Infosys', 'Systems Engineer', 'Aptitude', 'MEDIUM', 'Choose the odd one out: 121, 169, 144, 196, 125', '125 is a perfect cube (5^3), while all others are perfect squares.', ARRAY['aptitude','number-theory','logical-reasoning']),
('Infosys', 'Systems Engineer', 'Aptitude', 'EASY', 'If ROSE is coded as 6821, how is SAME coded in the same scheme?', 'Map each letter to its given digit by analyzing ROSE=6821; derive SAME accordingly. Candidate should identify the mapping pattern systematically.', ARRAY['aptitude','coding-decoding','logical-reasoning']),
('Infosys', 'Systems Engineer', 'Aptitude', 'MEDIUM', 'A sum of money doubles itself at compound interest in 10 years. In how many years will it become 8 times?', 'If P doubles in 10 years, it becomes 2^n times in 10n years. 8 = 2^3, so 30 years.', ARRAY['aptitude','compound-interest','exponential']),
('Infosys', 'Systems Engineer', 'Behavioral', 'EASY', 'Where do you see yourself in 5 years?', 'Look for realistic career progression goals, alignment with a technology domain, and interest in continuous learning within the company context.', ARRAY['behavioral','career-goals','motivation']),
('Infosys', 'Systems Engineer', 'Technical', 'HARD', 'What is a deadlock in OS? Explain the Banker''s algorithm.', 'Deadlock: four Coffman conditions (mutual exclusion, hold-and-wait, no preemption, circular wait). Banker''s algorithm: simulates resource allocation to ensure the system remains in a safe state.', ARRAY['operating-systems','deadlock','resource-allocation']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Wipro', 'Project Engineer', 'DSA', 'EASY', 'Write a program to find the GCD and LCM of two numbers.', 'GCD via Euclidean algorithm: gcd(a,b) = gcd(b, a%b); LCM = (a*b)/gcd(a,b).', ARRAY['math','recursion','number-theory']),
('Wipro', 'Project Engineer', 'DSA', 'MEDIUM', 'Given a sorted array that is rotated at an unknown pivot, find the index of the minimum element.', 'Binary search: compare mid with right; if mid > right, min is in the right half; else left half. O(log n).', ARRAY['binary-search','arrays','rotated-array']),
('Wipro', 'Project Engineer', 'DSA', 'EASY', 'Print all prime numbers up to n using the Sieve of Eratosthenes.', 'Initialize boolean array; for each prime p from 2, mark multiples as composite. O(n log log n).', ARRAY['math','sieve','arrays']),
('Wipro', 'Project Engineer', 'DSA', 'MEDIUM', 'Find the starting position of a given pattern in a text string.', 'Brute force O(n*m); mention KMP algorithm which uses a failure function for O(n+m) time.', ARRAY['strings','pattern-matching','kmp']),
('Wipro', 'Project Engineer', 'DSA', 'MEDIUM', 'Given an array, find the subarray with the maximum sum (Kadane''s algorithm).', 'Track current max ending here and global max; reset current sum to 0 if it goes negative. O(n).', ARRAY['arrays','dynamic-programming','kadanes']),
('Wipro', 'Project Engineer', 'DSA', 'HARD', 'Implement a trie (prefix tree) with insert, search, and startsWith operations.', 'Each TrieNode has a children map and an isEnd flag. Insert character by character; search traverses and checks isEnd; startsWith only traverses.', ARRAY['trie','strings','design']),
('Wipro', 'Project Engineer', 'Technical', 'EASY', 'What is the difference between stack and heap memory?', 'Stack: function call frames, local variables, LIFO, fast, size-limited. Heap: dynamic allocation, slower, managed by programmer or GC, larger.', ARRAY['memory-management','operating-systems','fundamentals']),
('Wipro', 'Project Engineer', 'Technical', 'MEDIUM', 'Explain the difference between JOIN types in SQL: INNER, LEFT, RIGHT, FULL OUTER.', 'INNER: only matching rows from both tables. LEFT: all from left + matching right. RIGHT: opposite. FULL OUTER: all rows from both with NULLs for non-matches.', ARRAY['sql','dbms','joins']),
('Wipro', 'Project Engineer', 'Technical', 'EASY', 'What is polymorphism? Explain compile-time and runtime polymorphism with examples.', 'Compile-time: method overloading (same name, different params). Runtime: method overriding via inheritance. Runtime polymorphism resolved via virtual dispatch table.', ARRAY['oop','polymorphism','java']),
('Wipro', 'Project Engineer', 'Technical', 'MEDIUM', 'What are design patterns? Explain Singleton, Factory, and Observer patterns.', 'Singleton: one instance globally. Factory: object creation without specifying class. Observer: publish-subscribe, objects get notified on state change.', ARRAY['design-patterns','oop','software-design']),
('Wipro', 'Project Engineer', 'Aptitude', 'EASY', 'What is 15% of 240?', '15/100 * 240 = 36.', ARRAY['aptitude','percentages','arithmetic']),
('Wipro', 'Project Engineer', 'Aptitude', 'MEDIUM', 'Three numbers are in the ratio 1:2:3 and their sum is 180. Find the largest number.', 'Parts: x + 2x + 3x = 180; x = 30; largest = 90.', ARRAY['aptitude','ratio','algebra']),
('Wipro', 'Project Engineer', 'Aptitude', 'MEDIUM', 'A clock shows 3:15. What is the angle between the minute and hour hand?', 'Hour hand at 97.5 degrees (3h15m * 0.5 deg/min); minute hand at 90 degrees; angle = 7.5 degrees.', ARRAY['aptitude','clocks','geometry']),
('Wipro', 'Project Engineer', 'Aptitude', 'EASY', 'If all Bloops are Razzies and all Razzies are Lazzies, are all Bloops definitely Lazzies?', 'Yes, by syllogistic reasoning (transitive property of set membership).', ARRAY['aptitude','logical-reasoning','syllogism']),
('Wipro', 'Project Engineer', 'Aptitude', 'MEDIUM', 'A number when divided by 342 leaves remainder 47. What remainder does it leave when divided by 18?', '342 = 18 * 19; so the number mod 18 equals 47 mod 18 = 11.', ARRAY['aptitude','remainders','number-theory']),
('Wipro', 'Project Engineer', 'Behavioral', 'EASY', 'Tell me about yourself and your key technical strengths.', 'Look for concise narrative: background, core skills with specific examples, and relevance to the role applied for.', ARRAY['behavioral','introduction','self-awareness']),
('Wipro', 'Project Engineer', 'Technical', 'HARD', 'Explain the concept of REST API design principles and what makes an API truly RESTful.', 'Six constraints: stateless, client-server, cacheable, layered system, uniform interface (resource identification via URIs, HATEOAS), optional code-on-demand.', ARRAY['networking','rest-api','web']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Accenture', 'Associate Software Engineer', 'DSA', 'EASY', 'Write a program to check if a number is an Armstrong number.', 'For a d-digit number, check if sum of each digit raised to power d equals the number itself. e.g. 153 = 1^3 + 5^3 + 3^3.', ARRAY['math','loops','number-theory']),
('Accenture', 'Associate Software Engineer', 'DSA', 'EASY', 'Find the duplicate element in an array of n+1 integers where values are between 1 and n.', 'XOR all elements and 1..n to cancel out unique values, or use Floyd''s cycle detection on the array treated as a linked list.', ARRAY['arrays','bit-manipulation','cycle-detection']),
('Accenture', 'Associate Software Engineer', 'DSA', 'MEDIUM', 'Implement a queue using two stacks.', 'Push: push to stack1. Pop: if stack2 empty, move all from stack1 to stack2; pop from stack2. Amortized O(1) per operation.', ARRAY['queue','stack','design']),
('Accenture', 'Associate Software Engineer', 'DSA', 'MEDIUM', 'Given a sorted array and a target, find the first and last occurrence of the target.', 'Binary search twice: once biased left (continue searching left half on match), once biased right.', ARRAY['binary-search','arrays','searching']),
('Accenture', 'Associate Software Engineer', 'DSA', 'MEDIUM', 'Find if a given undirected graph has a cycle.', 'DFS with parent tracking; if a visited neighbor is not the parent of the current node, a cycle exists.', ARRAY['graphs','dfs','cycle-detection']),
('Accenture', 'Associate Software Engineer', 'Technical', 'EASY', 'What is the difference between == and .equals() in Java?', '== compares object references (memory address); .equals() compares logical content. Always use .equals() for String comparison.', ARRAY['java','oop','strings']),
('Accenture', 'Associate Software Engineer', 'Technical', 'MEDIUM', 'What is a foreign key and how does it enforce referential integrity?', 'A foreign key in a child table references a primary key in a parent table; DBMS prevents insertion of orphan records or deletion of referenced parent rows.', ARRAY['dbms','sql','constraints']),
('Accenture', 'Associate Software Engineer', 'Technical', 'EASY', 'What is an exception in Java? Explain checked vs unchecked exceptions.', 'Checked exceptions must be handled or declared at compile time (e.g. IOException). Unchecked are runtime exceptions (e.g. NullPointerException) and do not require explicit handling.', ARRAY['java','exceptions','error-handling']),
('Accenture', 'Associate Software Engineer', 'Aptitude', 'EASY', 'The average of five consecutive odd numbers is 25. Find the largest number.', 'Let numbers be x, x+2, x+4, x+6, x+8; average = x+4 = 25; x = 21; largest = 29.', ARRAY['aptitude','averages','arithmetic']),
('Accenture', 'Associate Software Engineer', 'Aptitude', 'MEDIUM', 'A pipe fills a tank in 4 hours and another empties it in 6 hours. If both are open, in how many hours will the tank fill?', 'Net rate = 1/4 - 1/6 = 1/12; tank fills in 12 hours.', ARRAY['aptitude','pipes-cisterns','arithmetic']),
('Accenture', 'Associate Software Engineer', 'Aptitude', 'EASY', 'What comes next in the series: 1, 4, 9, 16, 25, __?', '36 (perfect squares: n^2).', ARRAY['aptitude','series','number-patterns']),
('Accenture', 'Associate Software Engineer', 'Aptitude', 'MEDIUM', 'From a pack of 52 cards, what is the probability of drawing a king or a heart?', 'P(King) = 4/52, P(Heart) = 13/52, P(King of Hearts) = 1/52; P(King or Heart) = (4+13-1)/52 = 16/52 = 4/13.', ARRAY['aptitude','probability','combinatorics']),
('Accenture', 'Associate Software Engineer', 'Aptitude', 'MEDIUM', 'Read the passage and identify the correct inference: "All fruits are healthy. Mangoes are fruits. Therefore, ___."', 'Answer should be: Mangoes are healthy. Tests deductive reasoning and attention to logical structure.', ARRAY['aptitude','verbal-reasoning','logical-reasoning']),
('Accenture', 'Associate Software Engineer', 'Behavioral', 'EASY', 'Why do you want to work at Accenture?', 'Look for awareness of Accenture''s consulting and technology services, global exposure, and interest in digital transformation projects.', ARRAY['behavioral','company-fit','motivation']),
('Accenture', 'Associate Software Engineer', 'Technical', 'MEDIUM', 'Explain the software development life cycle (SDLC) phases.', 'Requirement gathering, Analysis, Design, Implementation, Testing, Deployment, Maintenance. Mention Agile vs Waterfall trade-offs.', ARRAY['sdlc','software-engineering','process']),
('Accenture', 'Associate Software Engineer', 'Technical', 'HARD', 'Explain the difference between synchronous and asynchronous programming with examples.', 'Synchronous: blocking execution; async: non-blocking, uses callbacks/Promises/async-await. Example: reading a file sync blocks the thread; async allows other operations to proceed.', ARRAY['programming-concepts','async','concurrency']),
('Accenture', 'Associate Software Engineer', 'DSA', 'HARD', 'Given a stream of integers, design a system to find the median of all elements seen so far at any point.', 'Use a max-heap for lower half and min-heap for upper half; balance sizes; median is top of max-heap or average of both tops.', ARRAY['heap','design','streaming']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Cognizant', 'Programmer Analyst Trainee', 'DSA', 'EASY', 'Find the sum of digits of a given number.', 'Extract digits using modulo 10 and integer division; accumulate sum. Handle negative numbers by using absolute value.', ARRAY['math','loops','digits']),
('Cognizant', 'Programmer Analyst Trainee', 'DSA', 'EASY', 'Count the number of vowels and consonants in a string.', 'Iterate through characters; check membership in vowel set; count consonants as letters minus vowels.', ARRAY['strings','loops','frequency']),
('Cognizant', 'Programmer Analyst Trainee', 'DSA', 'MEDIUM', 'Given an array of 0s and 1s, move all 0s to the left and 1s to the right without using extra space.', 'Two pointers: left from start, right from end; swap 1s encountered from left with 0s from right.', ARRAY['arrays','two-pointer','in-place']),
('Cognizant', 'Programmer Analyst Trainee', 'DSA', 'MEDIUM', 'Find the longest common subsequence of two strings.', 'Classic DP: dp[i][j] = dp[i-1][j-1]+1 if chars match, else max(dp[i-1][j], dp[i][j-1]). O(m*n) time and space.', ARRAY['dynamic-programming','strings','subsequence']),
('Cognizant', 'Programmer Analyst Trainee', 'DSA', 'MEDIUM', 'Given an expression with brackets, check whether it is balanced.', 'Use a stack; push open brackets, pop on closing and check match; balanced if stack empty at end.', ARRAY['stack','strings','balanced-brackets']),
('Cognizant', 'Programmer Analyst Trainee', 'DSA', 'HARD', 'Find the number of ways to climb n stairs taking 1 or 2 steps at a time.', 'dp[n] = dp[n-1] + dp[n-2] with dp[1]=1, dp[2]=2. Equivalent to Fibonacci shifted by one.', ARRAY['dynamic-programming','recursion','fibonacci']),
('Cognizant', 'Programmer Analyst Trainee', 'Technical', 'EASY', 'What is the difference between a structure and a class in C++?', 'In C++, struct members are public by default; class members are private by default. Otherwise they are functionally identical including support for methods and inheritance.', ARRAY['cpp','oop','fundamentals']),
('Cognizant', 'Programmer Analyst Trainee', 'Technical', 'MEDIUM', 'Explain transaction management in DBMS with ACID properties.', 'Atomicity (all or nothing), Consistency (valid state to valid state), Isolation (transactions don''t interfere), Durability (committed data persists). Relate to commit/rollback.', ARRAY['dbms','transactions','acid']),
('Cognizant', 'Programmer Analyst Trainee', 'Technical', 'EASY', 'What is the difference between overloading and overriding?', 'Overloading: same method name, different parameters, same class, compile-time polymorphism. Overriding: same signature in subclass, runtime polymorphism.', ARRAY['oop','polymorphism','java']),
('Cognizant', 'Programmer Analyst Trainee', 'Aptitude', 'EASY', 'If 8 workers can complete a job in 6 days, how many days will 12 workers take?', 'Total work = 48 worker-days; 12 workers take 48/12 = 4 days.', ARRAY['aptitude','work-rate','arithmetic']),
('Cognizant', 'Programmer Analyst Trainee', 'Aptitude', 'MEDIUM', 'A shopkeeper marks up goods by 30% and then gives a 10% discount. Find the net profit percentage.', 'SP = 1.3 * 0.9 * CP = 1.17 * CP; profit = 17%.', ARRAY['aptitude','profit-loss','percentages']),
('Cognizant', 'Programmer Analyst Trainee', 'Aptitude', 'MEDIUM', 'How many 3-digit numbers are divisible by 7?', 'First: 105, Last: 994; count = (994-105)/7 + 1 = 128.', ARRAY['aptitude','divisibility','counting']),
('Cognizant', 'Programmer Analyst Trainee', 'Aptitude', 'EASY', 'Statement: "Some cats are dogs. All dogs are animals." Conclusion: Some cats are animals. True or False?', 'True; since some cats are dogs and all dogs are animals, those cats are also animals by syllogism.', ARRAY['aptitude','syllogism','logical-reasoning']),
('Cognizant', 'Programmer Analyst Trainee', 'Aptitude', 'MEDIUM', 'Arrange in ascending order of value: 3/7, 5/9, 2/5, 7/11.', 'Convert to decimals: 0.4286, 0.5556, 0.4, 0.6364; order: 2/5 < 3/7 < 5/9 < 7/11.', ARRAY['aptitude','fractions','comparison']),
('Cognizant', 'Programmer Analyst Trainee', 'Behavioral', 'EASY', 'Tell me about a team project you worked on and your specific contribution.', 'Look for clarity on individual role, collaboration skills, accountability, and measurable contribution to team outcome.', ARRAY['behavioral','teamwork','contribution']),
('Cognizant', 'Programmer Analyst Trainee', 'Technical', 'MEDIUM', 'What are the different types of software testing? Explain unit, integration, and regression testing.', 'Unit: individual components in isolation. Integration: combined modules interact correctly. Regression: verify existing functionality after changes. Mention automated testing tools.', ARRAY['testing','software-engineering','qa']),
('Cognizant', 'Programmer Analyst Trainee', 'Technical', 'HARD', 'Explain the difference between monolithic and microservices architecture and when to choose each.', 'Monolith: single deployable unit, simpler initially, harder to scale independently. Microservices: independent services, better scalability and fault isolation, higher operational complexity. Choose microservices when teams and domains are clearly bounded.', ARRAY['architecture','microservices','design']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('IBM', 'Application Developer', 'DSA', 'MEDIUM', 'Implement a min-heap and support insert and extract-min operations.', 'Use a dynamic array; insert at end and sift up; extract-min swaps root with last, removes last, and sifts down. O(log n) per operation.', ARRAY['heap','arrays','design']),
('IBM', 'Application Developer', 'DSA', 'EASY', 'Determine if two binary trees are identical.', 'Recursively check: both null (equal), one null (unequal), or values equal and both subtrees identical.', ARRAY['binary-tree','recursion','dfs']),
('IBM', 'Application Developer', 'DSA', 'MEDIUM', 'Find the shortest path in an unweighted graph from a source node to all other nodes.', 'BFS from source; maintain distance array initialized to -1; update on first visit. O(V+E).', ARRAY['graphs','bfs','shortest-path']),
('IBM', 'Application Developer', 'DSA', 'HARD', 'Solve the 0/1 Knapsack problem.', 'DP table dp[i][w] = max value using first i items and capacity w; either exclude item i or include it if weight permits. O(n*W).', ARRAY['dynamic-programming','knapsack','recursion']),
('IBM', 'Application Developer', 'DSA', 'MEDIUM', 'Convert a binary tree to a doubly linked list in-place.', 'In-order traversal; maintain a prev pointer and link current node''s left to prev and prev''s right to current.', ARRAY['binary-tree','linked-list','dfs']),
('IBM', 'Application Developer', 'DSA', 'EASY', 'Count the number of set bits (1s) in the binary representation of a number.', 'Brian Kernighan''s algorithm: n = n & (n-1) clears the lowest set bit; count iterations until n=0. O(number of set bits).', ARRAY['bit-manipulation','math','binary']),
('IBM', 'Application Developer', 'System Design', 'HARD', 'Design a distributed logging system for a large-scale microservices architecture.', 'Structured logs to Kafka; consumers write to Elasticsearch; Kibana for visualization; discuss log levels, correlation IDs for tracing, and retention policies.', ARRAY['distributed-systems','logging','kafka']),
('IBM', 'Application Developer', 'System Design', 'MEDIUM', 'Design a file storage system like Dropbox or IBM Cloud Object Storage.', 'Client-side chunking with deduplication (content hash); metadata server; block storage backend; sync via delta updates; versioning support.', ARRAY['distributed-systems','file-storage','scalability']),
('IBM', 'Application Developer', 'Technical', 'MEDIUM', 'What is the difference between a mutex and a semaphore?', 'Mutex: binary lock owned by a thread, used for mutual exclusion. Semaphore: counter-based, can be used for signaling or limiting concurrent access to a resource pool.', ARRAY['operating-systems','concurrency','synchronization']),
('IBM', 'Application Developer', 'Technical', 'HARD', 'Explain how an RDBMS query optimizer works.', 'Parses SQL to logical plan, generates multiple physical execution plans, estimates cost via statistics (cardinality, histograms), selects lowest-cost plan.', ARRAY['dbms','query-optimization','performance']),
('IBM', 'Application Developer', 'Technical', 'MEDIUM', 'What is Docker? Explain containers vs virtual machines.', 'Docker packages application and dependencies into containers sharing the host OS kernel. VMs include a full OS; containers are lighter, faster to start, less isolated but more efficient.', ARRAY['devops','containers','docker']),
('IBM', 'Application Developer', 'Technical', 'EASY', 'What is CI/CD? Explain the typical stages in a pipeline.', 'Continuous Integration: automated build and test on code commit. Continuous Delivery/Deployment: automated packaging and release to production. Stages: build, test, code analysis, artifact storage, deploy.', ARRAY['devops','cicd','software-engineering']),
('IBM', 'Application Developer', 'Behavioral', 'MEDIUM', 'Describe a time you identified a process inefficiency and improved it.', 'Look for problem identification, initiative to act, stakeholder alignment, measurable improvement in speed or quality.', ARRAY['behavioral','process-improvement','initiative']),
('IBM', 'Application Developer', 'Behavioral', 'EASY', 'How do you stay updated with emerging technologies in your field?', 'Look for concrete habits: reading technical blogs, contributing to open source, attending conferences, completing online courses, and applying learnings to side projects.', ARRAY['behavioral','continuous-learning','growth']),
('IBM', 'Application Developer', 'Technical', 'MEDIUM', 'Explain the concept of eventual consistency and where it is used.', 'In distributed systems, replicas may temporarily diverge but will converge given no new updates. Used in Dynamo-style databases, DNS, and shopping carts where availability > strict consistency.', ARRAY['distributed-systems','consistency','databases']),
('IBM', 'Application Developer', 'DSA', 'MEDIUM', 'Given a string with brackets, numbers, and letters, implement a decoder where k[encoded_string] repeats the encoded string k times.', 'Use two stacks (counts and strings); push on ''['', pop and repeat on '']'', else build current string.', ARRAY['stack','strings','parsing']),
('IBM', 'Application Developer', 'Technical', 'HARD', 'What is the difference between optimistic and pessimistic locking in databases?', 'Pessimistic: lock the record on read, preventing others from modifying until released. Optimistic: no lock on read; validate at write that no conflict occurred (version number or timestamp check).', ARRAY['dbms','concurrency','locking']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Capgemini', 'Analyst', 'DSA', 'EASY', 'Write a program to swap two numbers without using a temporary variable.', 'Use arithmetic (a=a+b; b=a-b; a=a-b) or XOR (a^=b; b^=a; a^=b). Note overflow risk with arithmetic for large integers.', ARRAY['math','bit-manipulation','fundamentals']),
('Capgemini', 'Analyst', 'DSA', 'EASY', 'Find the frequency of each element in an array.', 'Use a hashmap; iterate through array and increment count for each element. O(n) time and space.', ARRAY['arrays','hashmap','frequency']),
('Capgemini', 'Analyst', 'DSA', 'MEDIUM', 'Given a number n, generate all valid combinations of n pairs of parentheses.', 'Backtracking: add open bracket if open count < n; add close bracket if close count < open count. Base case when length equals 2n.', ARRAY['backtracking','recursion','strings']),
('Capgemini', 'Analyst', 'DSA', 'MEDIUM', 'Sort an array of 0s, 1s, and 2s (Dutch National Flag problem) in a single pass.', 'Three pointers: low, mid, high. Swap based on value at mid: 0 goes to low, 1 stays, 2 goes to high. O(n), O(1).', ARRAY['arrays','two-pointer','sorting']),
('Capgemini', 'Analyst', 'DSA', 'HARD', 'Find the minimum cost to connect all cities using Prim''s or Kruskal''s algorithm (Minimum Spanning Tree).', 'Kruskal: sort edges by weight, add if no cycle (Union-Find). Prim: greedily add min-weight edge from visited set. Both O(E log E).', ARRAY['graphs','mst','greedy']),
('Capgemini', 'Analyst', 'DSA', 'MEDIUM', 'Write a recursive program to solve the Tower of Hanoi problem.', 'Base case: move 1 disk. Recursive: move n-1 to aux, move nth to dest, move n-1 from aux to dest. 2^n - 1 total moves.', ARRAY['recursion','divide-and-conquer','math']),
('Capgemini', 'Analyst', 'Technical', 'EASY', 'What is the difference between HTTP and HTTPS?', 'HTTP transfers data in plaintext; HTTPS uses TLS/SSL encryption for confidentiality and integrity. HTTPS requires a digital certificate from a CA.', ARRAY['networking','http','security']),
('Capgemini', 'Analyst', 'Technical', 'MEDIUM', 'Explain the concept of multithreading and thread synchronization in Java.', 'Multiple threads share process memory; synchronization via synchronized keyword, locks, or concurrent utilities prevents race conditions and ensures data consistency.', ARRAY['java','concurrency','multithreading']),
('Capgemini', 'Analyst', 'Technical', 'EASY', 'What is an ERD (Entity Relationship Diagram) and what are its components?', 'ERD models database structure with Entities (tables), Attributes (columns), and Relationships (associations) with cardinality (1:1, 1:N, M:N).', ARRAY['dbms','data-modeling','erd']),
('Capgemini', 'Analyst', 'Aptitude', 'EASY', 'If the simple interest on Rs 2000 for 3 years at 5% per annum is added to the principal, find the total amount.', 'SI = 2000 * 3 * 5 / 100 = 300; Total = 2300.', ARRAY['aptitude','simple-interest','arithmetic']),
('Capgemini', 'Analyst', 'Aptitude', 'MEDIUM', 'In how many ways can the letters of the word ENGINEER be arranged?', 'Word has 8 letters: E appears 3 times, N appears 2 times, G, I, R once each. Arrangements = 8! / (3! * 2!) = 3360.', ARRAY['aptitude','permutations','combinatorics']),
('Capgemini', 'Analyst', 'Aptitude', 'MEDIUM', 'A sphere has radius r. If the radius is doubled, by what factor does the volume increase?', 'V = (4/3)πr^3; new V = (4/3)π(2r)^3 = 8 * old V; volume increases by factor 8.', ARRAY['aptitude','geometry','mensuration']),
('Capgemini', 'Analyst', 'Aptitude', 'EASY', 'Complete the analogy: Doctor : Hospital :: Teacher : __', 'School. Tests understanding of functional relationship between person and their workplace.', ARRAY['aptitude','analogies','verbal-reasoning']),
('Capgemini', 'Analyst', 'Aptitude', 'MEDIUM', 'A mixture contains milk and water in ratio 4:1. How much water should be added to 20 litres of this mixture to make the ratio 2:1?', 'Milk = 16L, Water = 4L currently; for ratio 2:1, water = 8L; add 4L of water.', ARRAY['aptitude','mixtures','ratio']),
('Capgemini', 'Analyst', 'Behavioral', 'EASY', 'Describe a situation where you had to manage multiple tasks simultaneously.', 'Look for prioritization strategy, time management skills, use of tools or frameworks, and ability to meet deadlines without compromising quality.', ARRAY['behavioral','time-management','multitasking']),
('Capgemini', 'Analyst', 'Technical', 'HARD', 'Explain the difference between synchronous and event-driven microservice communication patterns.', 'Synchronous: direct REST/gRPC calls, simpler but creates coupling and latency chains. Event-driven: publish events to a broker (Kafka/RabbitMQ), services consume asynchronously; better decoupling and resilience.', ARRAY['microservices','event-driven','architecture']),
('Capgemini', 'Analyst', 'DSA', 'EASY', 'Determine whether a given integer is a perfect square without using sqrt().', 'Binary search between 1 and n; check if mid*mid equals n. O(log n). Alternatively, sum of odd numbers: 1+3+5+... = n^2.', ARRAY['math','binary-search','number-theory']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('HCL Technologies', 'Software Engineer', 'DSA', 'EASY', 'Write a program to convert a decimal number to binary.', 'Divide by 2 repeatedly and collect remainders in reverse order. Or use bit shifting: check each bit from MSB.', ARRAY['math','binary','bit-manipulation']),
('HCL Technologies', 'Software Engineer', 'DSA', 'MEDIUM', 'Find the diameter of a binary tree (longest path between any two leaf nodes).', 'For each node, diameter through it = left height + right height; track global max. O(n) with combined height and diameter DFS.', ARRAY['binary-tree','dfs','recursion']),
('HCL Technologies', 'Software Engineer', 'DSA', 'MEDIUM', 'Implement merge sort and analyze its complexity.', 'Divide array in half, recursively sort both, merge two sorted halves. O(n log n) time, O(n) space. Stable sort.', ARRAY['sorting','divide-and-conquer','recursion']),
('HCL Technologies', 'Software Engineer', 'DSA', 'HARD', 'Given a list of projects and dependencies, find a valid order of task execution (Topological Sort).', 'Kahn''s BFS: build in-degree map, start with in-degree 0 nodes, reduce neighbor in-degrees on visit. Detect cycle if not all nodes processed.', ARRAY['graphs','topological-sort','bfs']),
('HCL Technologies', 'Software Engineer', 'DSA', 'EASY', 'Find the intersection of two arrays.', 'Use a hashset for array1; iterate array2 and collect elements found in set. Handle duplicates with a second set.', ARRAY['arrays','hashmap','set']),
('HCL Technologies', 'Software Engineer', 'Technical', 'EASY', 'What is the difference between synchronous and asynchronous I/O?', 'Synchronous I/O blocks the caller until operation completes. Asynchronous I/O allows the caller to continue; completion is signaled via callback, future, or event.', ARRAY['operating-systems','io','concurrency']),
('HCL Technologies', 'Software Engineer', 'Technical', 'MEDIUM', 'Explain the concept of connection pooling in databases.', 'Pre-creates a pool of database connections reused across requests; avoids overhead of establishing a new connection per query. Controlled by pool size, timeout, and idle settings.', ARRAY['dbms','performance','connection-pooling']),
('HCL Technologies', 'Software Engineer', 'Technical', 'MEDIUM', 'What is OAuth 2.0 and how does it work?', 'Authorization framework allowing third-party apps to access user resources without exposing credentials. Flows: authorization code (web), implicit (deprecated), client credentials (server-to-server), device code.', ARRAY['security','oauth','authentication']),
('HCL Technologies', 'Software Engineer', 'Behavioral', 'EASY', 'Tell me about a time you had to debug a complex issue under pressure.', 'Look for systematic debugging approach, calmness under pressure, use of tools/logs, root cause analysis, and steps taken to prevent recurrence.', ARRAY['behavioral','debugging','problem-solving']),
('HCL Technologies', 'Software Engineer', 'Behavioral', 'MEDIUM', 'Describe a situation where you had to explain a technical concept to a non-technical stakeholder.', 'Look for use of analogies, simplification without loss of accuracy, checking for understanding, and adapting communication style.', ARRAY['behavioral','communication','stakeholder-management']),
('HCL Technologies', 'Software Engineer', 'Technical', 'HARD', 'How does Kubernetes orchestrate containers? Explain pods, services, and deployments.', 'Pod: smallest unit, one or more containers sharing network/storage. Deployment: manages pod replicas and rolling updates. Service: stable network endpoint abstracting pod IPs.', ARRAY['devops','kubernetes','containers']),
('HCL Technologies', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a list of intervals, merge all overlapping intervals.', 'Sort by start time; iterate and merge if current interval overlaps with last merged (current.start <= last.end).', ARRAY['arrays','sorting','intervals']),
('HCL Technologies', 'Software Engineer', 'System Design', 'HARD', 'Design a real-time dashboard for monitoring server health metrics.', 'Agents on servers push metrics to a time-series DB (InfluxDB/Prometheus); Grafana for visualization; alert manager for threshold breaches; discuss data retention and downsampling.', ARRAY['monitoring','distributed-systems','time-series']),
('HCL Technologies', 'Software Engineer', 'Technical', 'MEDIUM', 'What is the difference between horizontal and vertical scaling?', 'Vertical: add more CPU/RAM to existing server (scale up); limited by hardware ceiling. Horizontal: add more servers (scale out); requires load balancing and stateless design.', ARRAY['scalability','architecture','distributed-systems']),
('HCL Technologies', 'Software Engineer', 'DSA', 'HARD', 'Find all unique subsets of a set that may contain duplicates.', 'Sort the array; backtracking with skip condition: if current element equals previous at the same depth level, skip to avoid duplicates.', ARRAY['backtracking','arrays','subsets']),
('HCL Technologies', 'Software Engineer', 'Technical', 'EASY', 'What is the difference between a stack and a queue? Give real-world use cases.', 'Stack: LIFO — used in function call stack, undo operations, DFS. Queue: FIFO — used in BFS, print spooler, task scheduling.', ARRAY['data-structures','stack','queue']);
INSERT INTO company_questions (company_name, role, category, difficulty, question, ideal_answer, tags) VALUES
('Tech Mahindra', 'Software Engineer', 'DSA', 'EASY', 'Write a program to print the Fibonacci sequence up to n terms.', 'Iterative: maintain two variables for the last two values. Recursive: F(n) = F(n-1) + F(n-2), but note exponential time without memoization.', ARRAY['recursion','dynamic-programming','math']),
('Tech Mahindra', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a matrix, print its elements in spiral order.', 'Use four boundary pointers (top, bottom, left, right); traverse right, down, left, up in a loop, shrinking boundaries. O(m*n).', ARRAY['arrays','matrix','simulation']),
('Tech Mahindra', 'Software Engineer', 'DSA', 'MEDIUM', 'Find if a path exists between two nodes in a directed graph.', 'BFS or DFS from the source node; return true if target is encountered. O(V+E).', ARRAY['graphs','dfs','bfs']),
('Tech Mahindra', 'Software Engineer', 'DSA', 'HARD', 'Given a weighted directed graph, find the shortest path from a source to all vertices (Dijkstra''s algorithm).', 'Min-heap of (distance, node); relax edges greedily. O((V+E) log V). Does not work with negative edge weights.', ARRAY['graphs','dijkstra','shortest-path']),
('Tech Mahindra', 'Software Engineer', 'DSA', 'EASY', 'Count the number of occurrences of a character in a string.', 'Iterate over each character and compare; increment counter on match. O(n).', ARRAY['strings','loops','frequency']),
('Tech Mahindra', 'Software Engineer', 'Technical', 'MEDIUM', 'What is the difference between overriding and hiding in Java?', 'Overriding applies to instance methods and is resolved at runtime (dynamic dispatch). Hiding applies to static methods and is resolved at compile time based on the reference type.', ARRAY['java','oop','polymorphism']),
('Tech Mahindra', 'Software Engineer', 'Technical', 'EASY', 'What are the different states of a thread in Java?', 'New, Runnable, Blocked, Waiting, Timed Waiting, Terminated. Explain transitions between states.', ARRAY['java','concurrency','threads']),
('Tech Mahindra', 'Software Engineer', 'Technical', 'MEDIUM', 'Explain stored procedures and triggers in SQL.', 'Stored procedure: precompiled SQL code callable by name, supports parameters. Trigger: automatically executes on INSERT/UPDATE/DELETE events on a table.', ARRAY['sql','dbms','stored-procedures']),
('Tech Mahindra', 'Software Engineer', 'Aptitude', 'EASY', 'What is 25% of 25% of 400?', '25% of 400 = 100; 25% of 100 = 25.', ARRAY['aptitude','percentages','arithmetic']),
('Tech Mahindra', 'Software Engineer', 'Aptitude', 'MEDIUM', 'A car covers a distance in 8 hours at 60 km/h. At what speed must it travel to cover the same distance in 6 hours?', 'Distance = 480 km; Speed = 480/6 = 80 km/h.', ARRAY['aptitude','speed-distance','arithmetic']),
('Tech Mahindra', 'Software Engineer', 'Aptitude', 'MEDIUM', 'In a family, there are 6 members A, B, C, D, E, F. A and B are a married couple. D is the son of C who is the brother of A. Identify F''s relation to D if F is the daughter of B.', 'A''s brother C has son D; A and B are married, and F is their daughter; thus F is cousin of D.', ARRAY['aptitude','blood-relations','logical-reasoning']),
('Tech Mahindra', 'Software Engineer', 'Aptitude', 'EASY', 'Which is greater: 2^40 or 4^20?', '4^20 = (2^2)^20 = 2^40; they are equal.', ARRAY['aptitude','exponents','math']),
('Tech Mahindra', 'Software Engineer', 'Behavioral', 'MEDIUM', 'Tell me about a time you failed and what you learned from it.', 'Look for honesty about the failure, genuine reflection, specific lessons learned, and evidence that those lessons changed subsequent behavior.', ARRAY['behavioral','growth-mindset','self-awareness']),
('Tech Mahindra', 'Software Engineer', 'Technical', 'HARD', 'Explain the internals of a relational database: B+ tree index structure and how it supports range queries.', 'B+ trees store data only at leaf nodes linked in sorted order; internal nodes are routing keys. Range queries traverse leaf-level linked list after finding start key. O(log n + k) for k results.', ARRAY['dbms','indexing','b-plus-tree']),
('Tech Mahindra', 'Software Engineer', 'DSA', 'MEDIUM', 'Given a string of numbers, add two numbers represented as strings without converting to integers.', 'Iterate from right to left, summing digits and carrying over. Handle different lengths by padding with zeros. O(max(m,n)).', ARRAY['strings','math','simulation']),
('Tech Mahindra', 'Software Engineer', 'System Design', 'MEDIUM', 'Design a simple task scheduling system that supports cron-like periodic job execution.', 'Job store with cron expressions; scheduler thread wakes up at next trigger time; executor pool runs jobs; discuss fault tolerance via persistent job state and at-least-once execution guarantees.', ARRAY['scheduling','distributed-systems','queues']);